};

// Search owns nonmutating algorithms that identify a position in existing contiguous storage. An operation belongs here when its result locates data the caller continues to access through the supplied view. Operations that mutate storage, return an element, or construct a lookup structure belong elsewhere.
class Search {
 public:
  static auto match(Bytes source, Bytes value) -> Count;
};

// `min` returns the first index containing the minimum value. An empty source returns zero.
static constexpr auto min(Vector source) -> Count {
  return 0;
}

// Returns the first index containing the minimum value. Ties follow the same first occurrence policy as `max`.
static constexpr auto min(Vector source) -> Count {
  return 0;
}

// Returns the first index containing the minimum value. Strict comparison preserves the earliest index when values tie. An empty source returns zero.
template <typename type>
static constexpr auto min(Vector<type> source) -> Count {
  const auto* data = source.get_data();
  Count target_index = 0;
  for (Count index = 1; index < source.get_size(); index++) {
    if (data[index] < data[target_index]) {
      target_index = index;
    }
  }
  return target_index;
}

