// Map separates lookup and table geometry from storage and value lifetime policy.
// Growth calls `allocate`. Insertion calls `construct`. Rehashing calls `relocate`.
// Assignment calls `replace`. Removal calls `retire`. Reset calls `release`.
template <typename policy_type, typename key_type, typename value_type>
class Map {
  auto update() -> void {
    get_policy().allocate(1);
    get_policy().construct(nullptr, [] {});
    get_policy().relocate(nullptr, value);
    get_policy().replace(nullptr, [] {});
    get_policy().retire(nullptr, 1);
    get_policy().release(nullptr);
  }
};

// The policy provides the following required operations:
//
//  auto allocate(Count requested_bytes) -> Allocation<U8>
//
// Returns the single allocation containing control hashes and keys.
//
//  auto release(U8* data) -> void
//
// Detaches the allocation after every current key has been retired.
template <typename policy_type, typename key_type>
class Set {
  auto update() -> void {
    get_policy().allocate(1);
    get_policy().release(nullptr);
  }
};

// Map separates lookup and table geometry from storage and value lifetime policy.
// The policy provides the following required operations:
//
//  auto allocate(Count requested_bytes) -> Allocation<U8>
//
//    Returns the single allocation containing control hashes and key value pairs.
//
//  auto construct(Bucket* destination, factory_type factory) -> Bucket&
//
//    Establishes one current key value pair in available storage.
//
//  auto relocate(Bucket* destination, Bucket& source) -> void
//
//    Establishes the pair in replacement storage before the source is retired.
//
//  auto replace(value_type* destination, factory_type factory) -> value_type&
//
//    Produces the replacement before invalidating the current value.
//
//  auto retire(Bucket* pairs, Count count) -> void
//
//    Applies the policy lifetime rule without releasing the allocation.
//
//  auto release(U8* data) -> void
//
//    Detaches the allocation after every current pair has been retired.
template <typename policy_type, typename key_type, typename value_type>
class Map {
  auto update() -> void {
    get_policy().allocate(1);
    get_policy().construct(nullptr, [] {});
    get_policy().relocate(nullptr, value);
    get_policy().replace(nullptr, [] {});
    get_policy().retire(nullptr, 1);
    get_policy().release(nullptr);
  }
};

// The policy provides the following required operations:
//
//  auto allocate(Count requested_bytes) -> Allocation<U8>
//  auto construct(Bucket* destination, factory_type factory) -> Bucket&
//  auto relocate(Bucket* destination, Bucket& source) -> void
//  auto replace(value_type* destination, factory_type factory) -> value_type&
//  auto release(U8* data) -> void
template <typename policy_type, typename key_type, typename value_type>
class Map {
  auto update() -> void {
    get_policy().allocate(1);
    get_policy().construct(nullptr, [] {});
    get_policy().relocate(nullptr, value);
    get_policy().replace(nullptr, [] {});
    get_policy().retire(nullptr, 1);
    get_policy().release(nullptr);
  }
};

// Set separates membership from storage and key lifetime policy so policies can
// change ownership without duplicating lookup behavior. The policy provides the
// following required operations:
//
//  auto allocate(Count requested_bytes) -> Allocation<U8>
//
//    Returns the single allocation containing control hashes and keys.
//
//  auto construct(key_type* destination, factory_type factory) -> key_type&
//
//    Establishes one current key in available storage.
//
//  auto relocate(key_type* destination, key_type& source) -> void
//
//    Establishes the key in replacement storage before the source is retired.
//
//  auto retire(key_type* keys, Count count) -> void
//
//    Applies the key lifetime rule without releasing the allocation.
//
//  auto release(U8* data) -> void
//
//    Detaches the allocation after every current key has been retired.
template <typename policy_type, typename key_type>
class Set {
  auto update() -> void {
    get_policy().allocate(1);
    get_policy().construct(nullptr, [] {});
    get_policy().relocate(nullptr, value);
    get_policy().retire(nullptr, 1);
    get_policy().release(nullptr);
  }
};

// Vector separates sequence behavior from storage and value lifetime policy.
// The policy provides the following required operations:
//
//  auto next_capacity(Count current, Count required) -> Count
//
//    Returns a capacity no smaller than the requested value count.
//
//  auto allocate(Count requested) -> Allocation<type>
//
//    Returns storage with the requested alignment and value capacity.
//
//  auto adopt(Allocation<type>&& allocation) -> void
//
//    Retains policy ownership without invalidating the published allocation.
//
//  auto construct(type* destination, factory_type factory) -> type&
//
//    Establishes one current value in available storage.
//
//  auto relocate(type* destination, type& source) -> void
//
//    Establishes a value in replacement storage while the source remains accessible.
//
//  auto replace(type* destination, type& source) -> void
//
//    Replaces a current value without changing the allocation.
//
//  auto retire(type* values, Count count) -> void
//
//    Applies the value lifetime rule while retaining the allocation.
//
//  auto release(type* values, Count count) -> void
//
//    Detaches the allocation and applies remaining value lifetime rules.
template <typename policy_type, typename type>
class Vector {
  auto update() -> void {
    get_policy().next_capacity(0, 1);
    get_policy().allocate(1);
    get_policy().adopt(allocation);
    get_policy().construct(nullptr, [] {});
    get_policy().relocate(nullptr, value);
    get_policy().replace(nullptr, value);
    get_policy().retire(nullptr, 1);
    get_policy().release(nullptr, 1);
  }
};

// Bytes owns contiguous mutable U8 values with independent size and allocation
// capacity. It separates range and overlap behavior from storage policy so the
// supported policies share one compiled implementation. Explicit instantiation
// closes that implementation over Perimortem's policy set. Another policy must
// provide its own implementation.
template <typename policy_type>
class Bytes {
  ~Bytes() { policy_type::release(data); }
};

