// Applications can therefore build execution policies independently of the
// platform thread creation and naming APIs.
//
// Startup copies the name into thread local storage before returning. The
// callback context remains caller storage and must stay accessible until the
// callback returns. Moving transfers the handle and its join obligation while
// leaving the source in its default state.
class Thread {
};

// Stores one lexical path with normalized separators.
//
// Filesystem canonicalization requires an opened root and can race with later
// path use. Path stays lexical so callers can normalize stable cache keys
// before a filesystem operation opens the location.
class Path {
 public:
  static constexpr Count max_size = 510;

  Path() = default;
  Path(Core::View::Bytes path);
};

// Path gives filesystem callers one canonical language for selecting host
// locations without exposing native drive, separator or working directory
// syntax. Anchor bindings are captured when Perimortem loads, so later working
// directory and environment changes do not retarget an existing Path.
//
// Components use UTF-8 and `/`. Empty components, a trailing separator, `.` and
// `..` are rejected so one location has one lexical representation. Links remain
// host filesystem objects and carry no Path confinement guarantee.
//
// Path stores an Anchor and a View over the component bytes without allocating.
// The caller keeps those bytes alive and unchanged through every use. Canonical
// serialization can use caller storage. Native emission allocates because it
// combines the components with a captured host anchor and terminates the result.
class Path {
 public:
  Path() = delete;
  static constexpr auto create(Anchor anchor, Core::View::Bytes components)
      -> Core::Storage::Option<Path>;
  static constexpr auto parse(Core::View::Bytes canonical)
      -> Core::Storage::Result<Path, Failure>;
  constexpr auto serialize(Core::Access::Bytes destination) const -> Count;
  auto emit() const -> Core::Storage::Result<Native, EmissionFailure>;
};

// Path provides callers a canonical normalized filesystem representation. It
// ensures stable identity and can serialize or emit native paths efficiently.
class Path {
 public:
  static constexpr Count max_size = 510;
  Path() = default;
};

// Packet stores one protocol header without allocating. It accepts at most 512
// bytes because the wire length field is nine bits. `create` returns None when
// the source exceeds that limit.
class Packet {
 public:
  static constexpr Count max_size = 512;
  static auto create(Core::View::Bytes source) -> Core::Storage::Option<Packet>;
};
